Here is the problem description:
<description>
This is an easier version of the problem. In this version, $$$n \le 6$$$.Marek is working hard on creating strong testcases to his new algorithmic problem. You want to know what it is? Nah, we're not telling you. However, we can tell you how he generates the testcases.Marek chooses an integer $$$n$$$ and $$$n^2$$$ integers $$$p_{ij}$$$ ($$$1 \le i \le n$$$, $$$1 \le j \le n$$$). He then generates a random bipartite graph with $$$2n$$$ vertices. There are $$$n$$$ vertices on the left side: $$$\ell_1, \ell_2, \dots, \ell_n$$$, and $$$n$$$ vertices on the right side: $$$r_1, r_2, \dots, r_n$$$. For each $$$i$$$ and $$$j$$$, he puts an edge between vertices $$$\ell_i$$$ and $$$r_j$$$ with probability $$$p_{ij}$$$ percent.It turns out that the tests will be strong only if a perfect matching exists in the generated graph. What is the probability that this will occur?It can be shown that this value can be represented as $$$\frac{P}{Q}$$$ where $$$P$$$ and $$$Q$$$ are coprime integers and $$$Q \not\equiv 0 \pmod{10^9+7}$$$. Let $$$Q^{-1}$$$ be an integer for which $$$Q \cdot Q^{-1} \equiv 1 \pmod{10^9+7}$$$. Print the value of $$$P \cdot Q^{-1}$$$ modulo $$$10^9+7$$$.
</description>

Here is the input specification:
<input_spec>
The first line of the input contains a single integer $$$n$$$ ($$$\mathbf{1 \le n \le 6}$$$). The following $$$n$$$ lines describe the probabilities of each edge appearing in the graph. The $$$i$$$-th of the lines contains $$$n$$$ integers $$$p_{i1}, p_{i2}, \dots, p_{in}$$$ ($$$0 \le p_{ij} \le 100$$$); $$$p_{ij}$$$ denotes the probability, in percent, of an edge appearing between $$$\ell_i$$$ and $$$r_j$$$.
</input_spec>

Here are additional notes:
<notes>
NoteIn the first sample test, each of the $$$16$$$ graphs below is equally probable. Out of these, $$$7$$$ have a perfect matching:  Therefore, the probability is equal to $$$\frac{7}{16}$$$. As $$$16 \cdot 562\,500\,004 = 1 \pmod{10^9+7}$$$, the answer to the testcase is $$$7 \cdot 562\,500\,004 \mod{(10^9+7)} = 937\,500\,007$$$.
</notes>

Here are sample inputs:
<sample_inputs>
<input>
2
50 50
50 50
</input>
<input>
3
3 1 4
1 5 9
2 6 5
</input>
</sample_inputs>

Here is the source code:
<source_code>
#include <bits/stdc++.h>
using namespace std;
const int mod=1e9+7;
const int N=(1<<20)+5;
int n,lim,ans,p1[N],p2[N];
int flag[10][10],a[10][10],h[10][10][10];
int fpow(int x,int y) {
	int res=1;
	while (y) {
		if (y&1) res=1ll*res*x%mod;
		x=1ll*x*x%mod,y>>=1;
	}
	return res;
}
int inv(int x) { return fpow(x,mod-2); }
bool check(int x,int y,int z) {
	int a[3]={x,y,z},d[3]={0,1,2};
	do {
		if (flag[a[d[0]]][1] && flag[a[d[1]]][2] && flag[a[d[2]]][3]) return 1;
	} while (next_permutation(d,d+3));
	return 0;
}

void dfs1(int P,int x,int y) {
	if (x==7 && y==1) {
		int sta=0;
		for (int i=1; i<=6; i++)
			for (int j=i+1; j<=6; j++)
				for (int k=j+1; k<=6; k++) 
					if (check(i,j,k)) {
						int x=1;
			            while (x==i || x==j || x==k) x++;
			            int y=x+1;
			            while (y==i || y==j || y==k) y++;
			            int z=y+1;
			            while (z==i || z==j || z==k) z++;
			            sta|=h[x][y][z];
					}
		p1[sta]=(p1[sta]+P)%mod;
//		if (P!=0) printf("!!!!! %d %d\n",sta,p1[sta],P);
		return;
	}
	flag[x][y]=1;
	if (y==3) dfs1(1ll*P*a[x][y]%mod,x+1,1);
	else dfs1(1ll*P*a[x][y]%mod,x,y+1);
	flag[x][y]=0;
	if (y==3) dfs1(1ll*P*(mod+1-a[x][y])%mod,x+1,1);
	else dfs1(1ll*P*(mod+1-a[x][y])%mod,x,y+1);
}

void dfs2(int P,int x,int y) {
	if (x==7 && y==4) {
		int sta=0;
		for (int i=1; i<=6; i++)
			for (int j=i+1; j<=6; j++)
				for (int k=j+1; k<=6; k++) 
					if (check(i,j,k)) sta|=h[i][j][k];
		p2[sta]=(p2[sta]+P)%mod;
//		if (P!=0) printf("!!!! %d %d %d\n",sta,p2[sta],P);
		ans=(ans+1ll*p1[lim^sta]*P%mod)%mod;
		return;
	}
	flag[x][y-3]=1;
	if (y==6) dfs2(1ll*P*a[x][y]%mod,x+1,4);
	else dfs2(1ll*P*a[x][y]%mod,x,y+1);
	flag[x][y-3]=0;
	if (y==6) dfs2(1ll*P*(mod+1-a[x][y])%mod,x+1,4);
	else dfs2(1ll*P*(mod+1-a[x][y])%mod,x,y+1);
}

int main() {
	scanf("%d",&n);
	for (int i=1; i<=n; i++)
		for (int j=1; j<=n; j++)
			scanf("%d",&a[i][j]),a[i][j]=1ll*a[i][j]*inv(100)%mod;
	for (int i=n+1; i<=6; i++) a[i][i]=1;
	int tot=0;
    for (int i=1; i<=6; i++)
			for (int j=i+1; j<=6; j++)
				for (int k=j+1; k<=6; k++) 
					h[i][j][k]=1<<tot++;
	dfs1(1,1,1);
//	printf("!!!!!!\n");
	lim=(1<<20)-1;
	for (int i=0; i<=19; i++)
		 for (int j=0; j<=lim; j++) 
		 	if (j>>i&1) p1[j]=(p1[j]+p1[j^1<<i])%mod;
//	printf("!!! %d\n",p1[lim]);
	dfs2(1,1,4);
	ans=(mod+1-ans)%mod;
	printf("%d\n",ans);
	return 0;
}


